export default {
  name: "Search-Input",
  data: function data() {
    return {
      inpValue: '',
      searchEngine: ["https://www.google.com/search?q=", "https://cn.bing.com/search?q=", "https://www.baidu.com/s?wd=", "https://www.zhihu.com/search?q=", "https://github.com/search?q="],
      currentIocn: ['google.svg', 'bing.svg', 'baidu.svg', 'zhihu.svg', 'github.svg'],
      INDEX: 1,
      //默认搜索引擎
      hiddenBlock: true
    };
  },
  methods: {
    autoFocus: function autoFocus() {
      this.$refs.Input.focus();
    },
    // 按下回车搜索函数
    getBaidu: function getBaidu() {
      if (this.inpValue) {
        window.open("".concat(this.searchEngine[this.INDEX]).concat(this.inpValue), "_blank");
      }
    },
    showSearchSelect: function showSearchSelect() {
      this.hiddenBlock = !this.hiddenBlock;
    },
    getIndex: function getIndex(e) {
      this.INDEX = e.currentTarget.getAttribute("data-index");
    }
  },
  watch: {
    hiddenBlock: function hiddenBlock(val) {
      var _this = this;
      if (!val) {
        document.documentElement.addEventListener('click', function () {
          _this.hiddenBlock = true;
        });
      } else {
        document.documentElement.removeEventListener('click', function () {});
      }
    }
  }
