export default {
  name: 'CommonDialog',
  props: {
    dialogVisible: {
      type: Boolean,
      "default": false
    }
  },
  data: function data() {
    return {
      /* 赋值时机不同于mounted */
      childDialogVisible: this.dialogVisible
    };
  },
  watch: {
    dialogVisible: function dialogVisible(newV) {
      this.childDialogVisible = newV;
    },
    childDialogVisible: function childDialogVisible(newV) {
      this.$emit('update:dialogVisible', newV);
    }
  },
  methods: {
    handleConfirm: function handleConfirm(yes) {
      if (yes) {
        // 执行确定操作
        this.$emit('confirm');
      } else {
        this.$emit('update:dialogVisible', false);
      }
    }
  }
};